// The Worker's entry point (wrangler.jsonc `main`). It answers byte-range
// requests for the project demo videos (see ./ranges.ts) and hands every other
// request to the worker `opennextjs-cloudflare build` generates, unchanged.
// Only paths listed in `assets.run_worker_first` reach this before the static
// assets; every other file is still served by Cloudflare straight from them.
// https://opennext.js.org/cloudflare/howtos/custom-worker

// @ts-ignore: generated by `opennextjs-cloudflare build`, absent before it runs
import openNext from "../.open-next/worker.js";
import { isVideoPath, serveVideo, type AssetFetcher } from "./ranges";

type Env = { ASSETS: AssetFetcher };
type Handler = { fetch(request: Request, env: Env, ctx: unknown): Promise<Response> };

export default {
  async fetch(request: Request, env: Env, ctx: unknown): Promise<Response> {
    if (isVideoPath(new URL(request.url).pathname)) {
      // On a miss (or any error) the app gets the request: Next renders its
      // 404, or OpenNext serves the file whole, as before.
      const video = await serveVideo(request, env.ASSETS).catch(() => null);
      if (video) return video;
    }
    return (openNext as Handler).fetch(request, env, ctx);
  },
};
